import {Config, Field} from 'alinea'
import {createCMS} from 'alinea/server'

export const Page = Config.document('Page', {
  fields: {
    body: Field.text('Body', {multiline: true})
  }
})

export const cms = createCMS({
  schema: {Page},
  workspaces: {
    main: Config.workspace('Example', {
      source: 'content',
      mediaDir: 'static/media',
      roots: {
        pages: Config.root('Pages', {contains: ['Page']}),
        media: Config.media()
      }
    })
  },
  baseUrl: {
    development: 'http://localhost:5173',
    production: 'https://example.com'
  },
  handlerUrl: '/api/cms',
  adminPath: '/admin',
  publicDir: 'static',
  preview: true
})

import {createHandle} from 'alinea/sveltekit'
import {cms} from './cms'

export const handle = createHandle(cms)

import {sequence} from '@sveltejs/kit/hooks'
import {createHandle} from 'alinea/sveltekit'
import {cms} from './cms'

export const handle = sequence(
  createHandle({cms, previews: {widget: true}}),
  async ({event, resolve}) => {
    // Your own hook
    return resolve(event)
  }
)

import {error} from '@sveltejs/kit'
import {cms, Page} from '../../cms'

export async function load({params}) {
  const page = await cms.first({type: Page, url: `/${params.slug}`})
  if (!page) error(404)
  return {page}
}

